INSERT INTO data_plane_type (type_name,param_spec,capability_spec,"desc",desc_en) VALUES
	 ('arms','{"name":"root","type":"object","children":[{"name":"address","type":"string","desc":"Arms地址, 例如: https://arms.cn-hangzhou.aliyuncs.com","desc_en":"Arms Address, e.g. https://arms.cn-hangzhou.aliyuncs.com"},{"name":"accessKey","type":"string","desc":"Arms AccessKey","desc_en":"Arms AccessKey"},{"name":"accessSecret","type":"string","desc":"Arms AccessSecret","desc_en":"Arms AccessSecret"}]}','["RedMetric","ServiceInstance","Topology","Trace"]','<中文描述占位>','<en describe temp>'),
	 ('skywalking','{"name":"root","type":"object","children":[{"name":"address","type":"string","desc":"Skywalking 地址, 例如: http://10.0.0.0:8080","desc_en":"Skywalking Address, e.g. http://10.0.0.0:8080"},{"name":"user","type":"string","desc":"Skywalking 用户名","desc_en":"Skywalking Username"},{"name":"password","type":"string","desc":"Skywalking 密码","desc_en":"Skywalking Password"}]}','["RedMetric","ServiceInstance","Topology","Trace"]','<中文描述占位>','<en describe temp>'),
	 ('tempo','{"name":"root","type":"object","children":[{"name":"tempoAddress","type":"string","desc_en":"Tempo Address e.g. http://10.0.0.0:3200","desc":"Tempo地址 例如: http://10.0.0.0:3200"},{"name":"promethuesAddress","type":"string","desc_en":"PrometheusAddress e.g. http://10.0.0.0:9090","desc":"Prometheus地址 例如: http://10.0.0.0:9090"}]}','["RedMetric","ServiceInstance","Topology","Trace"]','<中文描述占位>','<en describe temp>'),
	 ('datadog','{"name":"root","type":"object","children":[{"name":"site","type":"string","desc_en":"DataDog Site, e.g. datadoghq.com","desc":"DataDog地址,示例: datadoghq.com"},{"name":"apiKey","type":"string","desc_en":"DataDog API Key of DataDog","desc":"DataDog API Key"},{"name":"appKey","type":"string","desc_en":"DataDog APP Key of DataDog","desc":"DataDog APP Key"},{"name":"env","type":"string","desc_en":"DataDog env, e.g. *","desc":"DataDog 环境,例如: *"}]}','["RedMetric","ServiceInstance","Topology","Log","Trace"]','## 所需Scope权限\n\n|名称|描述|\n|--|--|\n|timeseries_query|用于读取 Trace/Metric/Topology 数据|\n|apm_read|用于读取 Trace 数据|\n|logs_read_index_data|用于读取 Log 索引数据|\n|logs_read_data| 用于读取 Log 数据|\n','## Using Scopes\n\n|Name|Description|\n|--|--|\n|timeseries_query|Read Metric/Trace/Topology.|\n|apm_read|Read Trace Data.|\n|logs_read_index_data|Read log index data.|\n|logs_read_data|Read log data.|\n'),
	 ('signoz','{"name":"root","type":"object","children":[{"name":"address","type":"string","desc":"Signoz地址,例如: http://10.0.0.0:3200","desc_en":"Signoz Address, e.g. http://10.0.0.0:3200"},{"name":"apiKey","type":"string","desc":"Signoz API Key, 需要 Sigonz>=v0.85 开放API Key","desc_en":"Signoz API Key, need Signoz >= v0.85"}]}','["RedMetric","ServiceInstance","Topology","Trace","Log"]','<中文描述占位>','<en describe temp>');
